"""Full video memory: a texture that does not fit goes to system memory, or with flag 256 stops the program with a clear message,
unless textures without the flag can make room.

  vram.py BLITZCC PROGRAM.bb WORKDIR
"""
import os
import subprocess
import sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../tools"))
import procutil  # noqa: E402


def main():
    blitzcc, source, work = sys.argv[1], sys.argv[2], os.path.abspath(sys.argv[3])
    os.makedirs(work, exist_ok=True)
    exe = os.path.join(work, "vram")
    procutil.run([blitzcc, source, "-o", exe], check=True, stdout=subprocess.DEVNULL)
    env = dict(os.environ, BLITZLLVM_VRAM_LIMIT_MB="64")

    result = procutil.run([exe], env=env, capture_output=True, text=True, timeout=120)
    if result.returncode != 0 or "texture made" not in result.stderr or "Video memory is full" not in result.stderr:
        print("vram: a texture without flag 256 should go to system memory and the program end normally.\n%s" % result.stderr)
        return 1

    result = procutil.run([exe, "vram"], env=env, capture_output=True, text=True, timeout=120)
    if result.returncode == 0 or "texture made" in result.stderr or "out of video memory" not in result.stderr:
        print("vram: a texture with flag 256 should stop the program with 'out of video memory'.\n%s" % result.stderr)
        return 1

    # Textures without the flag make room for one with it.
    evict = os.path.join(work, "vram_evict")
    procutil.run([blitzcc, os.path.join(os.path.dirname(source), "vram_evict.bb"), "-o", evict], check=True, stdout=subprocess.DEVNULL)
    result = procutil.run([evict], env=dict(os.environ, BLITZLLVM_VRAM_LIMIT_MB="160"), capture_output=True, text=True, timeout=120)
    if result.returncode != 0 or "evicted ok" not in result.stderr:
        print("vram: textures without flag 256 should make room for one with it.\n%s" % result.stderr)
        return 1

    # Many textures of different sizes make room at once.
    many = os.path.join(work, "vram_evict_many")
    procutil.run([blitzcc, os.path.join(os.path.dirname(source), "vram_evict_many.bb"), "-o", many], check=True, stdout=subprocess.DEVNULL)
    result = procutil.run([many], env=dict(os.environ, BLITZLLVM_VRAM_LIMIT_MB="160"), capture_output=True, text=True, timeout=120)
    if result.returncode != 0 or "evicted many ok" not in result.stderr:
        print("vram: many textures without flag 256 should make room for one with it.\n%s" % result.stderr)
        return 1

    # What is drawn on textures that the allocator moved is still there.
    defrag = os.path.join(work, "vram_defrag")
    procutil.run([blitzcc, "-d", os.path.join(os.path.dirname(source), "vram_defrag.bb"), "-o", defrag], check=True, stdout=subprocess.DEVNULL)
    result = procutil.run([defrag], env=dict(os.environ, BLITZLLVM_DEFRAG_TEST="1", BLITZLLVM_DEFRAG_REPORT="1"), capture_output=True, text=True, timeout=120)
    moved = [line for line in result.stderr.splitlines() if line.startswith("defragmentation moved") and not line.endswith(" 0 images")]
    if result.returncode != 0 or "defrag ok" not in result.stderr or not moved:
        print("vram: textures that were moved together should keep their pictures (and some should have moved).\n%s" % result.stderr)
        return 1

    # The vertex and index buffers of meshes that the allocator moved still draw (also from the table of static draws), and the meshes can change.
    defrag_mesh = os.path.join(work, "vram_defrag_mesh")
    procutil.run([blitzcc, "-d", os.path.join(os.path.dirname(source), "vram_defrag_mesh.bb"), "-o", defrag_mesh], check=True, stdout=subprocess.DEVNULL)
    result = procutil.run([defrag_mesh], env=dict(os.environ, BLITZLLVM_DEFRAG_TEST="1", BLITZLLVM_DEFRAG_REPORT="1"), capture_output=True, text=True, timeout=120)
    moved = [line for line in result.stderr.splitlines() if line.startswith("defragmentation moved") and line.endswith(" mesh buffers") and not line.endswith(" 0 mesh buffers")]
    if result.returncode != 0 or "defrag mesh ok" not in result.stderr or not moved:
        print("vram: meshes whose buffers were moved together should still be drawn (and some buffers should have moved).\n%s" % result.stderr)
        return 1

    # The buffers of the window and of order independent transparency come before textures without flag 256.
    priority = os.path.join(work, "vram_priority")
    procutil.run([blitzcc, os.path.join(os.path.dirname(source), "vram_priority.bb"), "-o", priority], check=True, stdout=subprocess.DEVNULL)
    result = procutil.run([priority], env=dict(os.environ, BLITZLLVM_VRAM_LIMIT_MB="175"), capture_output=True, text=True, timeout=120)
    if result.returncode != 0 or "priority ok" not in result.stderr:
        print("vram: textures without flag 256 should make room for the buffers of order independent transparency.\n%s" % result.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
